  1→(function () {
  2→  "use strict";
  3→
  4→  // The intake questions per role and category, in form order. Keys match what the
  5→  // server accepts; blank answers are allowed and are what the follow-up round is
  6→  // for. The driver table mirrors app/schemas.DRIVER_INTAKE_QUESTIONS and uses
  7→  // actor-directed keys, so a driver answer can never be read as a rider answer.
  8→  var QUESTIONNAIRES_BY_ROLE = {
  9→    rider: {
 10→      route_deviation: [
 11→        { key: "expected_route", label: "What route did the app show you, and roughly how long was it?", kind: "open" },
 12→        { key: "was_route_agreed", label: "Did you and the driver agree to take a different route?", kind: "yes_no" },
 13→        { key: "asked_driver_to_stop", label: "Did you ask the driver to stop anywhere along the way?", kind: "yes_no" },
 14→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 15→      ],
 16→      no_show_charge: [
 17→        { key: "where_were_you", label: "Where were you when the trip was meant to start?", kind: "open" },
 18→        { key: "did_driver_contact_you", label: "Did the driver try to contact you?", kind: "yes_no" },
 19→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 20→      ]
 21→    },
 22→    driver: {
 23→      route_deviation: [
 24→        { key: "route_shown_to_driver", label: "What route did the app show you, and roughly how long was it?", kind: "open" },
 25→        { key: "route_agreed_with_rider", label: "Did you and the rider agree to take a different route?", kind: "yes_no" },
 26→        { key: "rider_requested_stop", label: "Did the rider ask you to stop anywhere along the way?", kind: "yes_no" },
 27→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 28→      ],
 29→      no_show_charge: [
 30→        { key: "driver_waiting_place", label: "Where did you wait, and for roughly how long?", kind: "open" },
 31→        { key: "driver_contacted_rider", label: "Did you try to call or message the rider?", kind: "yes_no" },
 32→        { key: "safety_concern", label: "At any point were you worried for your safety?", kind: "yes_no" }
 33→      ]
 34→    }
 35→  };
 36→
 37→  var CATEGORIES_BY_ROLE = {
 38→    rider: [
 39→      { id: "route_deviation", label: "My trip went the wrong way" },
 40→      { id: "no_show_charge", label: "I was charged for a trip that did not happen" },
 41→      { id: "property_damage_mess", label: "Property damage or a mess left behind" },
 42→      { id: "safety_incident", label: "A safety incident" },
 43→      { id: "other", label: "Something else" }
 44→    ],
 45→    driver: [
 46→      { id: "route_deviation", label: "A question about the route I took" },
 47→      { id: "no_show_charge", label: "A no-show or waiting fee" },
 48→      { id: "property_damage_mess", label: "A cleaning fee or damage report" },
 49→      { id: "safety_incident", label: "A safety incident" },
 50→      { id: "other", label: "Something else" }
 51→    ]
 52→  };
 53→
 54→  var STATUS_HEADINGS = {
 55→    decided: "We have made a decision",
 56→    under_review: "Your case is still under review",
 57→    passed_to_support: "Your report has been passed to our support team",
 58→    needs_info: "We need a little more information"
 59→  };
 60→
 61→  var state = {
 62→    category: null,
 63→    tripId: null,
 64→    trips: [],
 65→    runId: null
 66→  };
 67→
 68→  var stepCategory = document.getElementById("step-category");
 69→  var stepTrip = document.getElementById("step-trip");
 70→  var stepDetails = document.getElementById("step-details");
 71→  var outcomePanel = document.getElementById("outcome");
 72→  var categoryOptions = document.getElementById("category-options");
 73→  var tripOptions = document.getElementById("trip-options");
 74→  var questionList = document.getElementById("question-list");
 75→  var questionBoxes = document.getElementById("question-boxes");
 76→  var outcomeTitle = document.getElementById("outcome-title");
 77→  var outcomeReference = document.getElementById("outcome-reference");
 78→  var outcomeMessage = document.getElementById("outcome-message");
 79→  var outcomeQuestions = document.getElementById("outcome-questions");
 80→  var outcomeStatus = document.getElementById("outcome-status");
 81→
 82→  function element(tag, className, text) {
 83→    var node = document.createElement(tag);
 84→    if (className) {
 85→      node.className = className;
 86→    }
 87→    if (text !== undefined && text !== null) {
 88→      node.textContent = String(text);
 89→    }
 90→    return node;
 91→  }
 92→
 93→  function showError(id, message) {
 94→    var node = document.getElementById(id);
 95→    node.textContent = message;
 96→    node.hidden = false;
 97→  }
 98→
 99→  function clearError(id) {
100→    var node = document.getElementById(id);
101→    node.textContent = "";
102→    node.hidden = true;
103→  }
104→
105→  function show(node) {
106→    node.hidden = false;
107→  }
108→
109→  function hide(node) {
110→    node.hidden = true;
111→  }
112→
113→  function request(method, path, body) {
114→    var options = { method: method };
115→    if (body !== undefined) {
116→      options.headers = { "Content-Type": "application/json" };
117→      options.body = JSON.stringify(body);
118→    }
119→    return fetch(path, options).then(function (response) {
120→      return response.json().then(function (payload) {
121→        if (!response.ok) {
122→          var reason = payload && payload.error ? payload.error : "Something went wrong. Please try again.";
123→          throw new Error(reason);
124→        }
125→        return payload;
126→      });
127→    });
128→  }
129→
130→  // ------------------------------------------------------------- page role
131→
132→  // The shell's own marker selects the questionnaire and the category copy. A
133→  // missing marker is the original rider shell; any other explicit value refuses
134→  // the whole page. This is demo copy selection, not authentication: the role is
135→  // never read from the URL, the document body or the fixed driver account.
136→  var formSteps = document.getElementById("form-steps");
137→  var role = formSteps.getAttribute("data-filed-by");
138→  if (role === null) {
139→    role = "rider";
140→  }
141→  var QUESTIONNAIRES = QUESTIONNAIRES_BY_ROLE[role];
142→  var CATEGORIES = CATEGORIES_BY_ROLE[role];
143→  if (role !== "rider" && role !== "driver") {
144→    showError("category-error",
145→      "This filing page could not be loaded. Please return to the help page and try again.");
146→    return;
147→  }
148→
149→  // ------------------------------------------------------------- step one
150→
151→  CATEGORIES.forEach(function (category) {
152→    var card = element("button", "option-card", category.label);
153→    card.type = "button";
154→    card.addEventListener("click", function () {
155→      state.category = category.id;
156→      Array.prototype.forEach.call(categoryOptions.children, function (child) {
157→        child.classList.remove("selected");
158→      });
159→      card.classList.add("selected");
160→      document.getElementById("category-next").disabled = false;
161→      // Changing the category resets everything downstream (R3 page side): the trip
162→      // list belongs to the category, so a trip picked for one category must never
163→      // survive a switch to another.
164→      state.tripId = null;
165→      while (tripOptions.firstChild) {
166→        tripOptions.removeChild(tripOptions.firstChild);
167→      }
168→      document.getElementById("trip-next").disabled = true;
169→      clearError("trip-error");
170→      clearError("details-error");
171→      hide(stepTrip);
172→      hide(stepDetails);
173→    });
174→    categoryOptions.appendChild(card);
175→  });
176→
177→  document.getElementById("category-next").addEventListener("click", function () {
178→    clearError("category-error");
179→    hide(stepCategory);
180→    show(stepTrip);
181→    hide(stepDetails);
182→    loadTrips();
183→    window.scrollTo(0, 0);
184→  });
185→
186→  // ------------------------------------------------------------- step two
187→
188→  function loadTrips() {
189→    var boxes = tripOptions;
190→    while (boxes.firstChild) {
191→      boxes.removeChild(boxes.firstChild);
192→    }
193→    state.tripId = null;
194→    document.getElementById("trip-next").disabled = true;
195→    boxes.appendChild(element("p", "loading", "Loading trips…"));
196→    request("GET", "/api/trips?category=" + encodeURIComponent(state.category))
197→      .then(function (payload) {
198→        while (boxes.firstChild) {
199→          boxes.removeChild(boxes.firstChild);
200→        }
201→        state.trips = Array.isArray(payload.trips) ? payload.trips : [];
202→        if (state.trips.length === 0) {
203→          boxes.appendChild(element("p", "hint", "No trips are available in the sample dataset."));
204→          return;
205→        }
206→        state.trips.forEach(function (trip) {
207→          var meta = [trip.date, trip.kind_label].filter(Boolean).join(" · ");
208→          var lines = [
209→            element("strong", null, trip.label),
210→            element("span", "trip-meta", meta)
211→          ];
212→          var charge = "";
213→          if (trip.fare_sgd !== null && trip.fare_sgd !== undefined) {
214→            charge = " · SGD " + Number(trip.fare_sgd).toFixed(2)
215→              + (trip.charge_label ? " " + trip.charge_label : "");
216→          }
217→          var detail = element("span", "trip-meta", "");
218→          detail.textContent = "Trip " + trip.trip_id + charge;
219→          var card = element("button", "option-card trip-card");
220→          card.type = "button";
221→          lines.forEach(function (line) { card.appendChild(line); });
222→          card.appendChild(detail);
223→          card.addEventListener("click", function () {
224→            state.tripId = trip.trip_id;
225→            Array.prototype.forEach.call(boxes.children, function (child) {
226→              child.classList.remove("selected");
227→            });
228→            card.classList.add("selected");
229→            document.getElementById("trip-next").disabled = false;
230→          });
231→          boxes.appendChild(card);
232→        });
233→      })
234→      .catch(function (error) {
235→        while (boxes.firstChild) {
236→          boxes.removeChild(boxes.firstChild);
237→        }
238→        showError("trip-error", error.message);
239→      });
240→  }
241→
242→  document.getElementById("trip-back").addEventListener("click", function () {
243→    show(stepCategory);
244→    hide(stepTrip);
245→  });
246→
247→  document.getElementById("trip-next").addEventListener("click", function () {
248→    clearError("trip-error");
249→    hide(stepTrip);
250→    buildQuestions();
251→    show(stepDetails);
252→    window.scrollTo(0, 0);
253→  });
254→
255→  // --------------------------------------------------------- step three
256→
257→  function buildChoiceQuestion(question) {
258→    var field = element("div", "field");
259→    var label = element("label", null, question.label);
260→    // The choices container is a div, so a <label for> cannot point at it. The
261→    // question text reaches assistive tech via role="group" + aria-labelledby.
262→    label.id = "label-" + question.key;
263→    var choices = element("div", "choice-options");
264→    choices.id = "answer-" + question.key;
265→    choices.role = "group";
266→    choices.setAttribute("aria-labelledby", "label-" + question.key);
267→    var elaborate = element("textarea", "answer-input elaborate");
268→    elaborate.rows = 2;
269→    elaborate.setAttribute("data-elaborate-for", question.key);
270→    elaborate.placeholder = "Tell us more (optional)";
271→    elaborate.setAttribute("aria-label", "Tell us more: " + question.label);
272→    elaborate.hidden = true;
273→
274→    ["Yes", "No"].forEach(function (choice) {
275→      var button = element("button", "choice-button", choice);
276→      button.type = "button";
277→      button.setAttribute("data-choice", choice);
278→      button.setAttribute("aria-pressed", "false");
279→      button.dataset.questionKey = question.key;
280→      button.addEventListener("click", function () {
281→        if (!button.classList.contains("selected")) {
282→          elaborate.value = "";
283→        }
284→        Array.prototype.forEach.call(choices.children, function (sibling) {
285→          sibling.classList.remove("selected");
286→          sibling.setAttribute("aria-pressed", "false");
287→        });
288→        button.classList.add("selected");
289→        button.setAttribute("aria-pressed", "true");
290→        show(elaborate);
291→      });
292→      choices.appendChild(button);
