  1→/* Real-browser W30 contract: the trip step is a viewport-fit card with its own scroll region.
  2→ * Requires Puppeteer and a live mock server (python3 -m app.server style; no app writes).
  3→ *   PUPPETEER_MODULE=/path/to/puppeteer BROWSER_EXECUTABLE=/path/to/browser \
  4→ *     node tests/browser/w30_trip_scroll.cjs BASE_URL OUTPUT_JSON
  5→ * Battery hooks: W30_CSS_OVERRIDE / W30_JS_OVERRIDE serve a mutated party.css / party.js.
  6→ *
  7→ * Tall views (height >= 600) must fit the whole card on screen with a breathing gap, buttons
  8→ * included. Short views (height < 600) may fall back to page scroll but keep the card's top in
  9→ * view, keep a floor of two trip cards in the list, and reach the buttons by page scroll.
 10→ * Every view: one visible step at each stage, no horizontal overflow, a list that scrolls
 11→ * internally, an action bar that follows the cards, no clipped hover/selected card, a fade
 12→ * that shows only while more trips are below (read from real pixels), and a keyboard order
 13→ * of last card -> Back -> Continue.
 14→ */
 15→const assert = require('node:assert/strict');
 16→const fs = require('fs');
 17→const path = require('path');
 18→const puppeteer = require(process.env.PUPPETEER_MODULE || 'puppeteer');
 19→const base = process.argv[2] || 'http://127.0.0.1:55817';
 20→const output = process.argv[3];
 21→if (!output) throw new Error('OUTPUT_JSON is required');
 22→fs.mkdirSync(path.dirname(output), { recursive: true });
 23→const viewports = [[360, 740], [390, 844], [600, 900], [1200, 600], [1200, 700], [1200, 900],
 24→  [1200, 500], [360, 480], [800, 320]];
 25→const report = { views: [], errors: [], passed: false };
 26→const GAP = 16;
 27→
 28→(async () => {
 29→  const browser = await puppeteer.launch({ headless: true,
 30→    ...(process.env.BROWSER_EXECUTABLE ? { executablePath: process.env.BROWSER_EXECUTABLE } : {}),
 31→    args: ['--no-sandbox'] });
 32→  try {
 33→    for (const file of ['index.html', 'driver-filing.html']) {
 34→      for (const [width, height] of viewports) {
 35→        const tall = height >= 600;
 36→        const page = await browser.newPage();
 37→        const view = { file, width, height, tall, stages: [] };
 38→        report.views.push(view);
 39→        page.on('pageerror', e => report.errors.push(String(e)));
 40→        await page.setViewport({ width, height });
 41→        if (process.env.W30_CSS_OVERRIDE || process.env.W30_JS_OVERRIDE) {
 42→          await page.setRequestInterception(true);
 43→          page.on('request', r => {
 44→            if (process.env.W30_CSS_OVERRIDE && r.url().endsWith('/party/party.css')) {
 45→              return r.respond({ status: 200, contentType: 'text/css', body: fs.readFileSync(process.env.W30_CSS_OVERRIDE, 'utf8') });
 46→            }
 47→            if (process.env.W30_JS_OVERRIDE && r.url().endsWith('/party/party.js')) {
 48→              return r.respond({ status: 200, contentType: 'application/javascript', body: fs.readFileSync(process.env.W30_JS_OVERRIDE, 'utf8') });
 49→            }
 50→            return r.continue();
 51→          });
 52→        }
 53→        await page.goto(base + '/party/' + file, { waitUntil: 'networkidle0' });
 54→        await page.evaluate(() => document.fonts.ready);
 55→        const visible = () => page.evaluate(() =>
 56→          [...document.querySelectorAll('#form-steps > .step')].filter(e => !e.hidden).map(e => e.id));
 57→        const settle = () => new Promise(r => setTimeout(r, 250));
 58→
 59→        // Step 1 -> 2 on the second category (the route/no-show lists differ in height).
 60→        await page.click('#category-options .option-card:nth-child(1)');
 61→        await page.click('#category-next');
 62→        await page.waitForSelector('#trip-options .trip-card');
 63→        await settle();
 64→        assert.deepEqual(await visible(), ['step-trip'], 'only the trip step is visible');
 65→
 66→        const geo = () => page.evaluate(() => {
 67→          const rect = e => { const r = e.getBoundingClientRect(); return { top: r.top, bottom: r.bottom, left: r.left, right: r.right, height: r.height }; };
 68→          const card = document.getElementById('step-trip');
 69→          const list = document.getElementById('trip-options');
 70→          const bar = card.querySelector('.step-actions');
 71→          const cards = [...list.querySelectorAll('.trip-card')];
 72→          const hit = el => { const r = el.getBoundingClientRect(); const h = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2); return !!h && (h === el || el.contains(h)); };
 73→          const cs = getComputedStyle(list);
 74→          return { vh: innerHeight, vw: innerWidth, scrollY: scrollY, card: rect(card), list: rect(list), bar: rect(bar),
 75→            back: rect(document.getElementById('trip-back')), next: rect(document.getElementById('trip-next')),
 76→            backHit: hit(document.getElementById('trip-back')), nextHit: document.getElementById('trip-next').disabled ? null : hit(document.getElementById('trip-next')),
 77→            scrollable: list.scrollHeight > list.clientHeight + 1, listClient: list.clientHeight,
 78→            hScroll: list.scrollWidth > list.clientWidth + 1, pageOverflow: document.documentElement.scrollWidth - innerWidth,
 79→            tallestCard: Math.max(...cards.map(c => c.getBoundingClientRect().height)), count: cards.length,
 80→            visibleCardsHit: cards.filter(c => { const r = c.getBoundingClientRect(), l = list.getBoundingClientRect(); return r.top >= l.top && r.bottom <= l.bottom && r.top >= 0 && r.bottom <= innerHeight; }).every(c => hit(c)),
 81→            overscroll: cs.overscrollBehaviorY, overflowY: cs.overflowY, bgImage: cs.backgroundImage, bgAttach: cs.backgroundAttachment };
 82→        });
 83→        const g = await geo();
 84→        view.stages.push({ stage: 'trip-entered', ...g });
 85→        assert.ok(g.pageOverflow <= 0, 'no horizontal page overflow');
 86→        assert.ok(g.card.top >= 0, 'the card heading is on screen');
 87→        assert.equal(g.scrollable, true, 'the list scrolls inside its own region');
 88→        assert.equal(g.hScroll, false, 'no horizontal scroll inside the region');
 89→        assert.equal(g.overflowY, 'auto');
 90→        assert.equal(g.overscroll, 'contain');
 91→        assert.ok(g.list.bottom <= g.bar.top + 0.5, 'the bar follows the list');
 92→        assert.equal(g.visibleCardsHit, true, 'every fully visible trip is the element at its own centre');
 93→        assert.ok(g.card.bottom >= g.bar.bottom - 0.5, 'the bar stays inside the card');
 94→        assert.ok(g.listClient >= 2 * g.tallestCard - 1, 'the list keeps a floor of two trip cards');
 95→        if (tall) {
 96→          assert.ok(g.card.top >= GAP - 1, 'breathing room above the card: ' + g.card.top);
 97→          assert.ok(g.card.bottom <= g.vh - GAP + 1, 'breathing room below the card: ' + g.card.bottom + ' of ' + g.vh);
 98→          assert.ok(g.next.bottom <= g.vh && g.back.bottom <= g.vh, 'Continue/Back are on screen on entry');
 99→          assert.equal(g.backHit, true, 'Back is the element at its own centre');
100→        } else {
101→          // Floor mode: page scroll reaches the buttons.
102→          await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
103→          await settle();
104→          const low = await geo();
105→          assert.ok(low.next.bottom <= low.vh && low.back.bottom <= low.vh, 'page scroll reaches Continue/Back');
106→          assert.equal(low.backHit, true);
107→          await page.evaluate(() => document.getElementById('step-trip').scrollIntoView({ block: 'start' }));
108→          await settle();
109→        }
110→
111→        // Scroll the region itself; the page must not move, the last card must end inside it.
112→        const before = await page.evaluate(() => scrollY);
113→        await page.evaluate(() => { const l = document.getElementById('trip-options'); l.scrollTop = l.scrollHeight; });
114→        await settle();
115→        const end = await page.evaluate(() => {
116→          const l = document.getElementById('trip-options'); const last = l.lastElementChild.getBoundingClientRect(); const lr = l.getBoundingClientRect();
117→          return { lastInside: last.bottom <= lr.bottom + 0.5, scrollY: scrollY };
118→        });
119→        assert.equal(end.lastInside, true, 'the last trip can be scrolled fully into the region');
120→        assert.equal(end.scrollY, before, 'scrolling the list does not scroll the page');
121→        view.stages.push({ stage: 'list-scrolled-to-end', ...end });
122→
123→        // Fade: real pixels in the region's left gutter (no card paints there), just above its
124→        // bottom edge. At the top of the list the fade tints it; at the end it is the card white.
125→        async function gutterPixel() {
126→          // A screenshot clip is in DOCUMENT coordinates, so add the page scroll offset.
127→          const place = () => page.evaluate(() => { const r = document.getElementById('trip-options').getBoundingClientRect(); return { x: r.left + 4 + scrollX, y: r.bottom - 4 + scrollY, vy: r.bottom - 4 }; });
128→          let spot = await place();
129→          if (spot.vy < 0 || spot.vy >= (await page.evaluate(() => innerHeight))) {
130→            // Floor mode: the list's bottom edge is below the fold; page scroll brings it up.
131→            await page.evaluate(() => document.querySelector('#step-trip .step-actions').scrollIntoView({ block: 'end' }));
132→            await settle();
133→            spot = await place();
134→          }
135→          assert.ok(spot.vy >= 0 && spot.vy < (await page.evaluate(() => innerHeight)), 'list bottom edge is reachable');
136→          const b64 = await page.screenshot({ clip: { x: Math.max(0, Math.floor(spot.x)), y: Math.floor(spot.y), width: 1, height: 1 }, encoding: 'base64' });
137→          return page.evaluate(async b64 => { const img = new Image(); img.src = 'data:image/png;base64,' + b64; await img.decode();
138→            const c = document.createElement('canvas'); c.width = 1; c.height = 1; const x = c.getContext('2d'); x.drawImage(img, 0, 0); return [...x.getImageData(0, 0, 1, 1).data].slice(0, 3); }, b64);
139→        }
140→        const atEnd = await gutterPixel();
141→        await page.evaluate(() => { document.getElementById('trip-options').scrollTop = 0; });
142→        await settle();
143→        const atTop = await gutterPixel();
144→        view.stages.push({ stage: 'fade-pixels', atTop, atEnd });
145→        {
146→          assert.ok(atEnd.every(c => c >= 253), 'no fade once the list is scrolled to its end: ' + atEnd);
147→          assert.ok(atTop.some(c => c < 245), 'a fade shows at the bottom edge while more trips are below: ' + atTop);
148→        }
149→
150→        // Hover lift and selected border stay inside the region.
151→        await page.hover('#trip-options .trip-card:nth-child(1)');
152→        await settle();
153→        const lift = await page.evaluate(() => {
154→          const l = document.getElementById('trip-options').getBoundingClientRect(); const c = document.querySelector('#trip-options .trip-card').getBoundingClientRect();
155→          return { topGap: c.top - l.top, leftGap: c.left - l.left, rightGap: l.right - c.right };
156→        });
157→        assert.ok(lift.topGap >= 4 && lift.leftGap >= 4 && lift.rightGap >= 4, 'a lifted card is not clipped by the region: ' + JSON.stringify(lift));
158→        await page.click('#trip-options .trip-card:nth-child(1)');
159→        assert.equal(await page.$$eval('#trip-options .selected', e => e.length), 1, 'exactly one selected trip');
160→        assert.equal(await page.$eval('#trip-next', e => e.disabled), false);
161→
162→        // Keyboard: last card -> Back -> Continue; focusing a hidden card scrolls the region to it.
163→        await page.evaluate(() => document.querySelector('#trip-options .trip-card:last-child').focus());
164→        const focused = await page.evaluate(() => { const l = document.getElementById('trip-options').getBoundingClientRect(); const c = document.activeElement.getBoundingClientRect();
165→          return { inside: c.top >= l.top - 0.5 && c.bottom <= l.bottom + 0.5 }; });
166→        assert.equal(focused.inside, true, 'a keyboard-focused trip is scrolled into the region');
167→        await page.keyboard.press('Tab');
168→        assert.equal(await page.evaluate(() => document.activeElement.id), 'trip-back', 'Tab from the last trip reaches Back');
169→        await page.keyboard.press('Tab');
170→        assert.equal(await page.evaluate(() => document.activeElement.id), 'trip-next', 'then Continue');
171→
172→        // Forward, Back, forward again: one visible step each time, the trip card lands again.
173→        await page.evaluate(() => document.getElementById('trip-next').scrollIntoView({ block: 'center' }));
174→        await page.click('#trip-next');
175→        await page.waitForSelector('#step-details:not([hidden])');
176→        assert.deepEqual(await visible(), ['step-details']);
177→        await page.click('#details-back');
178→        await page.waitForSelector('#trip-options .trip-card');
179→        await settle();
180→        assert.deepEqual(await visible(), ['step-trip']);
181→        const again = await geo();
182→        view.stages.push({ stage: 'trip-after-details-back', ...again });
183→        assert.ok(again.card.top >= 0, 'the card lands again after Back from details');
184→        if (tall) {
185→          assert.ok(again.card.bottom <= again.vh - GAP + 1 && again.next.bottom <= again.vh, 'buttons on screen again');
186→        }
187→
188→        // Back to the category step: it is on screen with its Continue.
189→        await page.evaluate(() => document.getElementById('trip-back').scrollIntoView({ block: 'center' }));
190→        await page.click('#trip-back');
191→        await settle();
192→        assert.deepEqual(await visible(), ['step-category']);
193→        const cat = await page.evaluate(() => { const c = document.getElementById('step-category').getBoundingClientRect(); const n = document.getElementById('category-next').getBoundingClientRect(); return { top: c.top, nextBottom: n.bottom, vh: innerHeight }; });
194→        view.stages.push({ stage: 'category-after-back', ...cat });
195→        assert.ok(cat.top >= 0, 'the category card is not cut off at the top after Back');
196→        if (tall) assert.ok(cat.nextBottom <= cat.vh, 'category Continue is on screen after Back');
197→
198→        if (width === 390 && file === 'driver-filing.html') {
199→          await page.click('#category-options .option-card:nth-child(1)');
200→          await page.click('#category-next');
201→          await page.waitForSelector('#trip-options .trip-card');
202→          await settle();
203→          await page.screenshot({ path: path.join(path.dirname(output), 'w30-driver-390.png') });
204→        }
205→        await page.close();
206→      }
207→    }
208→    assert.deepEqual(report.errors, []);
209→    report.passed = true;
210→  } catch (e) { report.error = String(e); process.exitCode = 1; }
211→  finally {
212→    await browser.close();
213→    fs.mkdirSync(path.dirname(output), { recursive: true });
214→    fs.writeFileSync(output, JSON.stringify(report, null, 2) + '\n');
215→    console.log(JSON.stringify({ passed: report.passed, views: report.views.length,
216→      stages: report.views.reduce((n, v) => n + v.stages.length, 0), error: report.error, output }));
217→  }
218→})().catch(e => { console.error(e); process.exitCode = 1; });
